449	  it('feeds a schema rejection back as a tool_result the model can correct on its next round', async () => {
450	    const registry = new ToolRegistry();
451	    const executorInputs: Array<Record<string, unknown>> = [];
452	    registry.register(
453	      {
454	        name: 'lookup',
455	        description: 'looks things up',
456	        inputSchema: {type: 'object', properties: {q: {type: 'string'}}, required: ['q']},
457	      },
458	      async input => {
459	        executorInputs.push(input);
460	        return `found ${String(input.q)}`;
461	      }
462	    );
463	    const rounds: MessageChunk[][] = [
464	      [{type: 'tool_use', toolCall: {id: 'call-bad', name: 'lookup', input: {}}}, STOP_FOR_TOOL],
465	      [TOOL_CALL, STOP_FOR_TOOL],
466	      [{type: 'text', text: 'found x'}, STOP_DONE],
467	    ];
